import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String str = scanner.nextLine();
        StringBuilder res = new StringBuilder();
        int length = str.length();
        boolean found_at = false;

        // Check if '@' exists in the string
        for (int i = 0; i < length; i++) {
            if (str.charAt(i) == '@') {
                found_at = true;
            }
        }

        char[] chars = str.toCharArray();

        for (int i = 0; i < length; i++) {
            if (i + 2 < length && chars[i] == 'd' && chars[i + 1] == 'o' && chars[i + 2] == 't' && i != 0 && i != length - 3) {
                res.append('.');
                chars[i] = ' ';
                chars[i + 1] = ' ';
                chars[i + 2] = ' ';
            } else if (i + 1 < length && chars[i] == 'a' && chars[i + 1] == 't' && i != 0 && i != length - 2 && !found_at) {
                res.append('@');
                chars[i] = ' ';
                chars[i + 1] = ' ';
                found_at = true;
            } else if (chars[i] != ' ') {
                res.append(chars[i]);
            }
        }

        System.out.println(res.toString());
        scanner.close();
    }
}
